const uzCyrillicPairs = [["o'", "ў"], ["O'", "Ў"], ["g'", "ғ"], ["G'", "Ғ"], ["sh", "ш"], ["Sh", "Ш"], ["SH", "Ш"], ["ch", "ч"], ["Ch", "Ч"], ["CH", "Ч"], ["ya", "я"], ["Ya", "Я"], ["YA", "Я"], ["yo", "ё"], ["Yo", "Ё"], ["YO", "Ё"], ["yu", "ю"], ["Yu", "Ю"], ["YU", "Ю"], ["ye", "е"], ["Ye", "Е"], ["YE", "Е"], ["ts", "ц"], ["Ts", "Ц"], ["a", "а"], ["b", "б"], ["d", "д"], ["e", "е"], ["f", "ф"], ["g", "г"], ["h", "ҳ"], ["i", "и"], ["j", "ж"], ["k", "к"], ["l", "л"], ["m", "м"], ["n", "н"], ["o", "о"], ["p", "п"], ["q", "қ"], ["r", "р"], ["s", "с"], ["t", "т"], ["u", "у"], ["v", "в"], ["x", "х"], ["y", "й"], ["z", "з"], ["c", "к"], ["w", "в"], ["A", "А"], ["B", "Б"], ["D", "Д"], ["E", "Е"], ["F", "Ф"], ["G", "Г"], ["H", "Ҳ"], ["I", "И"], ["J", "Ж"], ["K", "К"], ["L", "Л"], ["M", "М"], ["N", "Н"], ["O", "О"], ["P", "П"], ["Q", "Қ"], ["R", "Р"], ["S", "С"], ["T", "Т"], ["U", "У"], ["V", "В"], ["X", "Х"], ["Y", "Й"], ["Z", "З"], ["C", "К"], ["W", "В"]];
const uzCyrillicProtected = ["UzYolButlash", "Bitum ERP", "MAN TGS", "Hikvision", "Telegram", "ERP", "PDF", "CSV", "XLSX", "Excel", "API", "ID", "SMS", "URL", "Email"];

const _uzKeepRe = new RegExp(
  [
    "[\\w.+-]+@[\\w-]+\\.[\\w.]+",
    "https?://\\S+",
    "\\{\\w+\\}",
    "\\b\\w+(?:_\\w+)+\\b",
    "\\b\\w+\\.(?:env|md|py|js|json|csv|pdf)\\b",
    "\\b\\d[\\w.,/:-]*",
    "\\b(?:" + uzCyrillicProtected.map((p) => p.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")).join("|") + ")\\b",
  ].join("|"),
  "g"
);

function _uzTranslitWord(word) {
  // Word-initial "e" is "э"; done before the digraph pass so the e inside
  // ye/yo is never caught (in "Yetkazib" the boundary sits before the Y).
  let out = word.replace(/\be/g, "\u0001").replace(/\bE/g, "\u0002");
  for (const [latin, cyr] of uzCyrillicPairs) out = out.split(latin).join(cyr);
  return out.replace(/\u0001/g, "э").replace(/\u0002/g, "Э").replace(/['’]/g, "ъ");
}

function transliterateToCyrillic(text) {
  if (!text) return text;
  let out = "";
  let cursor = 0;
  _uzKeepRe.lastIndex = 0;
  let m;
  while ((m = _uzKeepRe.exec(text)) !== null) {
    out += _uzTranslitWord(text.slice(cursor, m.index)) + m[0];
    cursor = m.index + m[0].length;
  }
  return out + _uzTranslitWord(text.slice(cursor));
}
